UPDATE promotion_applicant_eligibility
SET account_type = #{accountType}, account_status = #{accountStatus}, registered_at = #{registeredAt}, source_version = #{sourceVersion},
last_source_event_id = #{lastSourceEventId}, updated_at = #{updatedAt}
WHERE user_id = #{userId}

UPDATE promotion_payout_account
SET owner_user_id = #{ownerUserId}, payout_type = #{payoutType}, payout_account_name = #{payoutAccountName},
payout_account_reference = #{payoutAccountReference}, status = #{status}, source_version = #{sourceVersion},
last_source_event_id = #{lastSourceEventId}, updated_at = #{updatedAt}
WHERE payout_account_id = #{payoutAccountId}

UPDATE promotion_commission_account
SET frozen4 = #{frozen4}, available4 = #{available4}, cash_debt4 = #{cashDebt4}, version = #{version}
WHERE promoter_user_id = #{promoterUserId} AND version = #{expectedVersion}

UPDATE promotion_funding_benefit
SET released_commission4 = #{releasedCommission4}, settled_paid_amount4 = #{settledPaidAmount4}
WHERE funding_lot_id = #{fundingLotId}

UPDATE promotion_funding_benefit
SET refunded_paid_amount4 = #{refundedPaidAmount4}, clawed_unreleased_commission4 = #{clawedUnreleasedCommission4},
reversed_released_commission4 = #{reversedReleasedCommission4}
WHERE funding_lot_id = #{fundingLotId}

UPDATE promotion_commission_account
SET available4 = #{available4}, withdrawing4 = #{withdrawing4}, version = #{version}
WHERE promoter_user_id = #{promoterUserId} AND version = #{expectedVersion}

UPDATE promotion_commission_account
SET available4 = #{available4}, withdrawing4 = #{withdrawing4}, cash_debt4 = #{cashDebt4}, version = #{version}
WHERE promoter_user_id = #{promoterUserId} AND version = #{expectedVersion}
